using System.Text.Json;
using System.Text.Json.Nodes;
using MemolineDemo.Editing;

namespace MemolineDemo;

internal static class RecordedBrushGroupChecks
{
    // Native session 4cd6b862a09449beaac155f15c3b308d, actual append IDs 2 and 35.
    // Only unrelated catalog nodes/shortcut tables were removed. The four-node
    // parent chain and complete brush core evidence retain their recorded metadata.
    internal static int Run()
    {
        int count = 0;
        void Check(bool value, string message) { if (!value) throw new InvalidOperationException(message); count++; }
        using var brushDocument = JsonDocument.Parse(BrushJson);
        using var catalogDocument = JsonDocument.Parse(CatalogJson);
        var brush = brushDocument.RootElement;
        var catalog = ToolCatalog.FromJson(catalogDocument.RootElement);
        var classifier = new BrushClassifier();
        Check(catalog.ParentGroupFor("G筆") == "沾水筆", "Actual CSP saved catalog resolves G pen through its recorded traditional-Chinese group.");
        Check(brush.GetProperty("state").GetProperty("name").GetString() == "G筆" &&
            brush.GetProperty("status").GetString() == "changed", "The actual confirmed brush observation is used without synthesizing a tool name.");
        var recorded = classifier.Classify(brush, catalog);
        Check(recorded.Eligible && recorded.Reasons.Count == 0, "Confirmed recorded G pen is an eligible drawing brush in the 沾水筆 group.");
        Check(!recorded.Causal && !recorded.ReadsReferenceLayers && !recorded.ReadsUnknownSource,
            "The spelling fix leaves the recorded property-based causal classification unchanged.");
        JsonElement CatalogWithParent(string parent)
        {
            var changed = JsonNode.Parse(CatalogJson)!;
            foreach (var node in changed["toolCatalog"]!["nodes"]!.AsArray())
                if (node!["id"]!.GetValue<string>() == "tool_22") node["name"] = parent;
            return JsonSerializer.SerializeToElement(changed);
        }
        Check(classifier.Classify(brush, ToolCatalog.FromJson(CatalogWithParent("蘸水笔"))).Eligible,
            "The explicit simplified-Chinese dip-pen group also resolves to a drawing tool.");
        Check(!classifier.Classify(brush, ToolCatalog.FromJson(CatalogWithParent("物件"))).Eligible,
            "An unsupported object-tool group stays ineligible even when its child is named G pen.");
        Check(!classifier.Classify(brush, ToolCatalog.FromJson(CatalogWithParent("自定义沾水筆物件"))).Eligible,
            "Containing the allowed group name does not grant eligibility to another tool family.");
        var ambiguous = JsonNode.Parse(CatalogJson)!;
        var nodes = ambiguous["toolCatalog"]!["nodes"]!.AsArray();
        var duplicate = nodes.Last()!.DeepClone(); duplicate["id"] = "duplicate-recorded-name"; nodes.Add(duplicate);
        Check(!classifier.Classify(brush, ToolCatalog.FromJson(JsonSerializer.SerializeToElement(ambiguous))).Eligible,
            "Duplicate G pen names retain the existing catalog ambiguity rejection.");
        var unknown = JsonNode.Parse(BrushJson)!; unknown["status"] = "unknown";
        Check(!classifier.Classify(JsonSerializer.SerializeToElement(unknown), catalog).Eligible,
            "Recognizing the parent group does not bypass an unconfirmed brush state.");
        Check(!classifier.Classify(brush, ToolCatalog.Empty()).Eligible,
            "A recorded brush name still requires an independently resolved tool catalog.");
        Console.WriteLine($"Recorded brush group checks passed: {count}.");
        return count;
    }

